{
  "name": "Sprint",
  "description": "Um aplicativo de desenvolvimento pessoal focado em execução de metas curtas e produtivas, projetado com foco em dispositivos móveis e alta escalabilidade."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Frequency = 'daily' | 'weekly' | 'monthly' | 'yearly';

export interface Completion {
  timestamp: number;
}

export interface Objective {
  id: string;
  title: string;
  description: string;
  frequency: Frequency;
  targetCount: number;
  duration: number; // in minutes
  color: string;
  createdAt: number;
  completions: Completion[];
}

export interface UserStats {
  totalSprints: number;
  longestStreak: number;
  currentStreak: number;
}

import React, { useState, useEffect, useCallback } from 'react';
import { Objective, Frequency } from './types';
import ObjectiveCard from './components/ObjectiveCard';
import AddObjectiveModal from './components/AddObjectiveModal';
import Header from './components/Header';
import StatsOverview from './components/StatsOverview';
import AIAssistant from './components/AIAssistant';

const App: React.FC = () => {
  const [objectives, setObjectives] = useState<Objective[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'objectives' | 'stats' | 'ai'>('objectives');

  // Persistence logic
  useEffect(() => {
    const saved = localStorage.getItem('sprint_objectives');
    if (saved) {
      try {
        setObjectives(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse objectives", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('sprint_objectives', JSON.stringify(objectives));
  }, [objectives]);

  const addObjective = (newObjective: Omit<Objective, 'id' | 'createdAt' | 'completions'>) => {
    const obj: Objective = {
      ...newObjective,
      id: crypto.randomUUID(),
      createdAt: Date.now(),
      completions: []
    };
    setObjectives(prev => [...prev, obj]);
    setIsModalOpen(false);
  };

  const deleteObjective = (id: string) => {
    if (confirm('Deseja realmente excluir este objetivo?')) {
      setObjectives(prev => prev.filter(o => o.id !== id));
    }
  };

  const completeSprint = (id: string) => {
    setObjectives(prev => prev.map(obj => {
      if (obj.id === id) {
        return {
          ...obj,
          completions: [...obj.completions, { timestamp: Date.now() }]
        };
      }
      return obj;
    }));
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-24 max-w-2xl mx-auto shadow-xl">
      <Header />

      <main className="p-4 space-y-6">
        {activeTab === 'objectives' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-xl font-bold text-gray-800">Seus Objetivos</h2>
              <button 
                onClick={() => setIsModalOpen(true)}
                className="bg-indigo-600 text-white w-10 h-10 rounded-full flex items-center justify-center shadow-lg hover:bg-indigo-700 transition-colors"
              >
                <i className="fas fa-plus"></i>
              </button>
            </div>

            {objectives.length === 0 ? (
              <div className="text-center py-12 px-6 bg-white rounded-2xl border-2 border-dashed border-gray-200">
                <div className="bg-indigo-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                  <i className="fas fa-bullseye text-indigo-400 text-2xl"></i>
                </div>
                <h3 className="text-gray-700 font-medium text-lg">Nenhum objetivo ainda</h3>
                <p className="text-gray-500 mt-2">Adicione seu primeiro objetivo para começar sua jornada de desenvolvimento.</p>
                <button 
                  onClick={() => setIsModalOpen(true)}
                  className="mt-6 px-6 py-2 bg-indigo-600 text-white rounded-lg font-semibold"
                >
                  Adicionar Objetivo
                </button>
              </div>
            ) : (
              <div className="grid gap-4">
                {objectives.map(obj => (
                  <ObjectiveCard 
                    key={obj.id} 
                    objective={obj} 
                    onComplete={() => completeSprint(obj.id)}
                    onDelete={() => deleteObjective(obj.id)}
                  />
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'stats' && <StatsOverview objectives={objectives} />}

        {activeTab === 'ai' && <AIAssistant objectives={objectives} />}
      </main>

      {/* Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 px-6 py-3 flex justify-between items-center max-w-2xl mx-auto z-40">
        <button 
          onClick={() => setActiveTab('objectives')}
          className={`flex flex-col items-center gap-1 ${activeTab === 'objectives' ? 'text-indigo-600' : 'text-gray-400'}`}
        >
          <i className="fas fa-list-check text-xl"></i>
          <span className="text-[10px] font-semibold">Sprint</span>
        </button>
        <button 
          onClick={() => setActiveTab('stats')}
          className={`flex flex-col items-center gap-1 ${activeTab === 'stats' ? 'text-indigo-600' : 'text-gray-400'}`}
        >
          <i className="fas fa-chart-line text-xl"></i>
          <span className="text-[10px] font-semibold">Progresso</span>
        </button>
        <button 
          onClick={() => setActiveTab('ai')}
          className={`flex flex-col items-center gap-1 ${activeTab === 'ai' ? 'text-indigo-600' : 'text-gray-400'}`}
        >
          <i className="fas fa-wand-magic-sparkles text-xl"></i>
          <span className="text-[10px] font-semibold">Insights AI</span>
        </button>
      </nav>

      <AddObjectiveModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSubmit={addObjective} 
      />
    </div>
  );
};

export default App;

import React from 'react';

const Header: React.FC = () => {
  return (
    <header className="bg-white px-6 pt-8 pb-6 flex items-center justify-between sticky top-0 z-30">
      <div>
        <h1 className="text-2xl font-black text-indigo-600 tracking-tight flex items-center gap-2">
          <i className="fas fa-bolt"></i> SPRINT
        </h1>
        <p className="text-gray-400 text-sm font-medium">Eleve seu desenvolvimento</p>
      </div>
      <div className="w-10 h-10 rounded-full bg-gray-100 border border-gray-200 overflow-hidden">
        <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Felix" alt="User Profile" />
      </div>
    </header>
  );
};

export default Header;

import React, { useMemo } from 'react';
import { Objective, Frequency } from '../types';

interface Props {
  objective: Objective;
  onComplete: () => void;
  onDelete: () => void;
}

const ObjectiveCard: React.FC<Props> = ({ objective, onComplete, onDelete }) => {
  const currentProgress = useMemo(() => {
    const now = new Date();
    const startOfPeriod = new Date();

    if (objective.frequency === 'daily') startOfPeriod.setHours(0, 0, 0, 0);
    else if (objective.frequency === 'weekly') {
      const day = startOfPeriod.getDay();
      const diff = startOfPeriod.getDate() - day + (day === 0 ? -6 : 1);
      startOfPeriod.setDate(diff);
      startOfPeriod.setHours(0, 0, 0, 0);
    } else if (objective.frequency === 'monthly') {
      startOfPeriod.setDate(1);
      startOfPeriod.setHours(0, 0, 0, 0);
    } else {
      startOfPeriod.setMonth(0, 1);
      startOfPeriod.setHours(0, 0, 0, 0);
    }

    return objective.completions.filter(c => c.timestamp >= startOfPeriod.getTime()).length;
  }, [objective.completions, objective.frequency]);

  const progressPercentage = Math.min((currentProgress / objective.targetCount) * 100, 100);

  const getFreqLabel = (f: Frequency) => {
    switch(f) {
      case 'daily': return 'dia';
      case 'weekly': return 'semana';
      case 'monthly': return 'mês';
      case 'yearly': return 'ano';
    }
  };

  return (
    <div className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100 hover:shadow-md transition-shadow">
      <div className="flex justify-between items-start mb-4">
        <div className="flex gap-3 items-center">
          <div className="w-10 h-10 rounded-xl flex items-center justify-center text-white text-lg font-bold" style={{ backgroundColor: objective.color }}>
            {objective.title.charAt(0).toUpperCase()}
          </div>
          <div>
            <h3 className="font-bold text-gray-800 text-lg leading-tight">{objective.title}</h3>
            <p className="text-gray-400 text-xs font-medium uppercase tracking-wider">
              {objective.targetCount}x por {getFreqLabel(objective.frequency)} • {objective.duration} min
            </p>
          </div>
        </div>
        <button onClick={onDelete} className="text-gray-300 hover:text-red-400 transition-colors p-1">
          <i className="fas fa-trash-alt"></i>
        </button>
      </div>

      <div className="space-y-3">
        <div className="flex justify-between items-end text-sm">
          <span className="text-gray-500 font-medium">Progresso atual</span>
          <span className="text-indigo-600 font-bold">{currentProgress} / {objective.targetCount}</span>
        </div>

        <div className="h-2.5 w-full bg-gray-100 rounded-full overflow-hidden">
          <div 
            className="h-full bg-indigo-500 rounded-full transition-all duration-500 ease-out" 
            style={{ width: `${progressPercentage}%` }}
          />
        </div>

        <div className="pt-2">
          <button 
            onClick={onComplete}
            disabled={currentProgress >= objective.targetCount}
            className={`w-full py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
              currentProgress >= objective.targetCount 
              ? 'bg-green-50 text-green-500 border border-green-100' 
              : 'bg-indigo-600 text-white active:scale-95 shadow-lg shadow-indigo-100'
            }`}
          >
            {currentProgress >= objective.targetCount ? (
              <><i className="fas fa-check-circle"></i> Meta Batida!</>
            ) : (
              <><i className="fas fa-play"></i> Iniciar Sprint</>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ObjectiveCard;

import React, { useState } from 'react';
import { Objective, Frequency } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (objective: Omit<Objective, 'id' | 'createdAt' | 'completions'>) => void;
}

const COLORS = ['#4f46e5', '#ef4444', '#10b981', '#f59e0b', '#8b5cf6', '#ec4899', '#06b6d4'];

const AddObjectiveModal: React.FC<Props> = ({ isOpen, onClose, onSubmit }) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [frequency, setFrequency] = useState<Frequency>('daily');
  const [targetCount, setTargetCount] = useState(1);
  const [duration, setDuration] = useState(15);
  const [selectedColor, setSelectedColor] = useState(COLORS[0]);

  if (!isOpen) return null;

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title) return;
    onSubmit({ title, description, frequency, targetCount, duration, color: selectedColor });
    reset();
  };

  const reset = () => {
    setTitle('');
    setDescription('');
    setFrequency('daily');
    setTargetCount(1);
    setDuration(15);
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-0 sm:p-4">
      <div className="bg-white w-full max-w-lg rounded-t-3xl sm:rounded-3xl p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-gray-800">Novo Objetivo</h2>
          <button onClick={onClose} className="text-gray-400 text-xl"><i className="fas fa-times"></i></button>
        </div>

        <form onSubmit={handleFormSubmit} className="space-y-5 overflow-y-auto max-h-[70vh] px-1 no-scrollbar">
          <div className="space-y-1">
            <label className="text-xs font-bold text-gray-400 uppercase">Título do Objetivo</label>
            <input 
              required
              value={title}
              onChange={e => setTitle(e.target.value)}
              placeholder="Ex: Estudar React"
              className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-bold text-gray-400 uppercase">Frequência</label>
              <select 
                value={frequency}
                onChange={e => setFrequency(e.target.value as Frequency)}
                className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500 appearance-none"
              >
                <option value="daily">Diário</option>
                <option value="weekly">Semanal</option>
                <option value="monthly">Mensal</option>
                <option value="yearly">Anual</option>
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-xs font-bold text-gray-400 uppercase">Vezes</label>
              <input 
                type="number"
                min="1"
                value={targetCount}
                onChange={e => setTargetCount(Number(e.target.value))}
                className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-gray-400 uppercase">Duração do Sprint (Minutos)</label>
            <input 
              type="range"
              min="5"
              max="120"
              step="5"
              value={duration}
              onChange={e => setDuration(Number(e.target.value))}
              className="w-full accent-indigo-600"
            />
            <div className="text-center font-bold text-indigo-600">{duration} min</div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 uppercase">Cor Identificadora</label>
            <div className="flex flex-wrap gap-3">
              {COLORS.map(c => (
                <button 
                  key={c}
                  type="button"
                  onClick={() => setSelectedColor(c)}
                  className={`w-8 h-8 rounded-full transition-transform ${selectedColor === c ? 'scale-125 ring-2 ring-offset-2 ring-gray-300' : ''}`}
                  style={{ backgroundColor: c }}
                />
              ))}
            </div>
          </div>

          <button 
            type="submit"
            className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all mt-4"
          >
            Criar Objetivo
          </button>
        </form>
      </div>
    </div>
  );
};

export default AddObjectiveModal;

import React from 'react';
import { Objective } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface Props {
  objectives: Objective[];
}

const StatsOverview: React.FC<Props> = ({ objectives }) => {
  const totalSprints = objectives.reduce((acc, obj) => acc + obj.completions.length, 0);

  const chartData = objectives.map(obj => ({
    name: obj.title.length > 8 ? obj.title.substring(0, 8) + '...' : obj.title,
    completions: obj.completions.length,
    color: obj.color
  }));

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-xl shadow-indigo-100">
          <p className="text-indigo-100 text-xs font-bold uppercase tracking-wider mb-1">Total Sprints</p>
          <h4 className="text-3xl font-black">{totalSprints}</h4>
          <i className="fas fa-rocket absolute top-4 right-4 text-indigo-500/30 text-4xl"></i>
        </div>
        <div className="bg-white rounded-3xl p-6 shadow-sm border border-gray-100">
          <p className="text-gray-400 text-xs font-bold uppercase tracking-wider mb-1">Ativos</p>
          <h4 className="text-3xl font-black text-gray-800">{objectives.length}</h4>
        </div>
      </div>

      <div className="bg-white rounded-3xl p-6 shadow-sm border border-gray-100">
        <h3 className="font-bold text-gray-800 mb-6">Execuções por Objetivo</h3>
        <div className="h-64 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#94a3b8' }} />
              <YAxis hide />
              <Tooltip 
                cursor={{ fill: 'transparent' }} 
                contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
              />
              <Bar dataKey="completions" radius={[8, 8, 8, 8]} barSize={32}>
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-white rounded-3xl p-6 shadow-sm border border-gray-100">
        <h3 className="font-bold text-gray-800 mb-4">Dicas de Consistência</h3>
        <ul className="space-y-4">
          <li className="flex gap-4 items-start">
            <div className="w-8 h-8 rounded-lg bg-orange-100 flex items-center justify-center text-orange-500 shrink-0">
              <i className="fas fa-lightbulb"></i>
            </div>
            <p className="text-sm text-gray-600 leading-relaxed">Mantenha seus sprints curtos (15-25 min) para evitar fadiga mental.</p>
          </li>
          <li className="flex gap-4 items-start">
            <div className="w-8 h-8 rounded-lg bg-blue-100 flex items-center justify-center text-blue-500 shrink-0">
              <i className="fas fa-calendar-check"></i>
            </div>
            <p className="text-sm text-gray-600 leading-relaxed">Tente completar seus objetivos matinais primeiro para ganhar momentum.</p>
          </li>
        </ul>
      </div>
    </div>
  );
};

export default StatsOverview;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Objective } from '../types';

interface Props {
  objectives: Objective[];
}

const AIAssistant: React.FC<Props> = ({ objectives }) => {
  const [insight, setInsight] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const generateInsight = async () => {
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `
        Aja como um mentor de desenvolvimento pessoal de alta performance. 
        Analise a lista de objetivos abaixo e forneça 3 conselhos práticos e motivacionais 
        específicos para melhorar o desempenho do usuário.
        Objetivos atuais: ${objectives.map(o => `${o.title} (${o.frequency}, ${o.targetCount}x)`).join(', ')}.
        Retorne em formato de tópicos curtos e inspiradores em Português.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });

      setInsight(response.text || "Não foi possível gerar insights agora. Tente novamente.");
    } catch (error) {
      console.error(error);
      setInsight("Houve um erro ao conectar com o mentor AI. Verifique sua conexão.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-br from-indigo-600 to-purple-700 rounded-3xl p-8 text-white relative overflow-hidden">
        <div className="relative z-10">
          <h3 className="text-2xl font-black mb-2 flex items-center gap-2">
            Mentor Sprint <i className="fas fa-sparkles text-yellow-300"></i>
          </h3>
          <p className="text-indigo-100 text-sm mb-6 leading-relaxed">
            Obtenha insights personalizados baseados nos seus objetivos atuais usando inteligência artificial de ponta.
          </p>
          <button 
            onClick={generateInsight}
            disabled={loading || objectives.length === 0}
            className="bg-white text-indigo-600 px-6 py-3 rounded-xl font-bold flex items-center gap-2 shadow-lg active:scale-95 transition-all disabled:opacity-50"
          >
            {loading ? (
              <><i className="fas fa-circle-notch animate-spin"></i> Analisando...</>
            ) : (
              <><i className="fas fa-brain"></i> Gerar Insights</>
            )}
          </button>
        </div>
        <i className="fas fa-wand-magic-sparkles absolute -bottom-4 -right-4 text-white/10 text-9xl"></i>
      </div>

      {insight && (
        <div className="bg-white rounded-3xl p-6 shadow-sm border border-indigo-100 animate-in fade-in duration-500">
          <div className="flex items-center gap-2 mb-4 text-indigo-600">
            <i className="fas fa-comment-dots"></i>
            <span className="font-bold text-sm uppercase tracking-widest">Recomendação do Mentor</span>
          </div>
          <div className="prose prose-sm text-gray-700 whitespace-pre-wrap leading-relaxed">
            {insight}
          </div>
        </div>
      )}

      {objectives.length === 0 && (
        <div className="text-center p-8 bg-gray-50 rounded-2xl border border-gray-200">
          <p className="text-gray-500 text-sm">Adicione objetivos para que o mentor AI possa analisá-los.</p>
        </div>
      )}
    </div>
  );
};

export default AIAssistant;

import React, { useState, useEffect } from 'react';
import { Objective } from './types';
import ObjectiveCard from './components/ObjectiveCard';
import AddObjectiveModal from './components/AddObjectiveModal';
import Header from './components/Header';
import StatsOverview from './components/StatsOverview';

const App: React.FC = () => {
  const [objectives, setObjectives] = useState<Objective[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'objectives' | 'stats'>('objectives');
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('sprint_theme');
    if (saved === 'light' || saved === 'dark') return saved;
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  // Theme effect
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('sprint_theme', theme);
  }, [theme]);

  // Persistence logic
  useEffect(() => {
    const saved = localStorage.getItem('sprint_objectives');
    if (saved) {
      try {
        setObjectives(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse objectives", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('sprint_objectives', JSON.stringify(objectives));
  }, [objectives]);

  const toggleTheme = () => setTheme(prev => prev === 'light' ? 'dark' : 'light');

  const addObjective = (newObjective: Omit<Objective, 'id' | 'createdAt' | 'completions'>) => {
    const obj: Objective = {
      ...newObjective,
      id: crypto.randomUUID(),
      createdAt: Date.now(),
      completions: []
    };
    setObjectives(prev => [...prev, obj]);
    setIsModalOpen(false);
  };

  const deleteObjective = (id: string) => {
    if (confirm('Deseja realmente excluir este objetivo?')) {
      setObjectives(prev => prev.filter(o => o.id !== id));
    }
  };

  const completeSprint = (id: string) => {
    setObjectives(prev => prev.map(obj => {
      if (obj.id === id) {
        return {
          ...obj,
          completions: [...obj.completions, { timestamp: Date.now() }]
        };
      }
      return obj;
    }));
  };

  return (
