}

const COLORS = ['#4f46e5', '#ef4444', '#10b981', '#f59e0b', '#8b5cf6', '#ec4899', '#06b6d4'];

const AddObjectiveModal: React.FC<Props> = ({ isOpen, onClose, onSubmit }) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [frequency, setFrequency] = useState<Frequency>('daily');
  const [targetCount, setTargetCount] = useState(1);
  const [duration, setDuration] = useState(15);
  const [selectedColor, setSelectedColor] = useState(COLORS[0]);

  if (!isOpen) return null;

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title) return;
    onSubmit({ title, description, frequency, targetCount, duration, color: selectedColor });
    reset();
  };

  const reset = () => {
    setTitle('');
    setDescription('');
    setFrequency('daily');
    setTargetCount(1);
    setDuration(15);
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-0 sm:p-4">
      <div className="bg-white dark:bg-gray-900 w-full max-w-lg rounded-t-3xl sm:rounded-3xl p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-gray-800 dark:text-gray-100">Novo Objetivo</h2>
          <button onClick={onClose} className="text-gray-400 dark:text-gray-600 text-xl hover:text-gray-600 transition-colors"><i className="fas fa-times"></i></button>
        </div>

        <form onSubmit={handleFormSubmit} className="space-y-5 overflow-y-auto max-h-[70vh] px-1 no-scrollbar">
          <div className="space-y-1">
            <label className="text-xs font-bold text-gray-400 dark:text-gray-500 uppercase">Título do Objetivo</label>
            <input 
              required
              value={title}
              onChange={e => setTitle(e.target.value)}
              placeholder="Ex: Estudar React"
              className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl px-4 py-3 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-bold text-gray-400 dark:text-gray-500 uppercase">Frequência</label>
              <select 
                value={frequency}
                onChange={e => setFrequency(e.target.value as Frequency)}
                className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl px-4 py-3 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 appearance-none"
              >
                <option value="daily">Diário</option>
                <option value="weekly">Semanal</option>
                <option value="monthly">Mensal</option>
                <option value="yearly">Anual</option>
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-xs font-bold text-gray-400 dark:text-gray-500 uppercase">Vezes</label>
              <input 
                type="number"
                min="1"
                value={targetCount}
                onChange={e => setTargetCount(Number(e.target.value))}
                className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl px-4 py-3 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-gray-400 dark:text-gray-500 uppercase">Duração do Sprint (Minutos)</label>
            <input 
              type="range"
              min="5"
              max="120"
              step="5"
              value={duration}
              onChange={e => setDuration(Number(e.target.value))}
              className="w-full accent-indigo-600"
            />
            <div className="text-center font-bold text-indigo-600 dark:text-indigo-400">{duration} min</div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-gray-400 dark:text-gray-500 uppercase">Cor Identificadora</label>
            <div className="flex flex-wrap gap-3">
              {COLORS.map(c => (
                <button 
                  key={c}
                  type="button"
                  onClick={() => setSelectedColor(c)}
                  className={`w-8 h-8 rounded-full transition-transform ${selectedColor === c ? 'scale-125 ring-2 ring-offset-2 ring-gray-300 dark:ring-gray-600' : ''}`}
                  style={{ backgroundColor: c }}
                />
              ))}
            </div>
          </div>

          <button 
            type="submit"
            className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-indigo-100 dark:shadow-none hover:bg-indigo-700 active:scale-95 transition-all mt-4"
          >
            Criar Objetivo
          </button>
        </form>
      </div>
    </div>
  );
};

