                startAngle={90}
                endAngle={450}
                paddingAngle={0}
                dataKey="value"
                stroke="none"
                animationDuration={1000}
              >
                <Cell fill={isDarkMode ? '#6366f1' : '#4f46e5'} />
                <Cell fill={isDarkMode ? '#1e293b' : '#f1f5f9'} />
              </Pie>
            </PieChart>
