import React, { useState, useEffect, useRef } from 'react';
import { Objective } from '../types';

interface Props {
  objective: Objective;
  onClose: () => void;
  onComplete: () => void;
}

const TimerView: React.FC<Props> = ({ objective, onClose, onComplete }) => {
  const [secondsLeft, setSecondsLeft] = useState(objective.duration * 60);
  const [isActive, setIsActive] = useState(true);
  const [isFinished, setIsFinished] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const totalSeconds = objective.duration * 60;

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (isActive && secondsLeft > 0 && !showExitConfirm) {
      timerRef.current = setInterval(() => {
        setSecondsLeft((prev) => prev - 1);
      }, 1000);
    } else if (secondsLeft === 0 && !isFinished) {
      handleSuccess();
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, secondsLeft, showExitConfirm, isFinished]);

  const handleSuccess = () => {
    setIsFinished(true);
    setIsActive(false);
    onComplete();
    // Delay para feedback visual de sucesso
    setTimeout(() => {
      onClose();
    }, 2000);
  };

  const handleManualExitAttempt = () => {
    setShowExitConfirm(true);
    // Pausar o timer enquanto decide
  };

  const confirmExit = () => {
    onClose(); // Fecha sem chamar onComplete
  };

  const formatTime = (totalSeconds: number) => {
    const mins = Math.floor(totalSeconds / 60);
    const secs = totalSeconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const progress = (secondsLeft / totalSeconds) * 100;
  const strokeDasharray = 283; 
  const strokeDashoffset = strokeDasharray - (progress / 100) * strokeDasharray;

  return (
    <div className="fixed inset-0 z-[60] bg-white dark:bg-gray-950 flex flex-col items-center justify-between p-8 animate-in fade-in zoom-in duration-300">
      {/* Header */}
      <div className="w-full flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="w-3 h-3 rounded-full animate-pulse" style={{ backgroundColor: objective.color }}></div>
          <h2 className="text-sm font-black text-gray-400 dark:text-gray-500 uppercase tracking-widest">{objective.title}</h2>
        </div>
        {!isFinished && !showExitConfirm && (
          <button 
            onClick={handleManualExitAttempt}
            className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 transition-colors"
          >
            <i className="fas fa-times text-xl"></i>
          </button>
        )}
      </div>

      {/* Timer Circle */}
      <div className="relative flex items-center justify-center w-72 h-72">
        <svg className="w-full h-full -rotate-90 transform" viewBox="0 0 100 100">
          <circle
            className="text-gray-100 dark:text-gray-900 stroke-current"
            strokeWidth="4"
            fill="transparent"
            r="45"
            cx="50"
            cy="50"
          />
          <circle
            className="transition-all duration-1000 ease-linear"
            stroke={objective.color}
            strokeWidth="4"
            strokeDasharray={strokeDasharray}
            strokeDashoffset={strokeDashoffset}
            strokeLinecap="round"
            fill="transparent"
            r="45"
            cx="50"
            cy="50"
          />
        </svg>
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          {isFinished ? (
            <div className="flex flex-col items-center animate-bounce">
              <i className="fas fa-check-circle text-6xl text-green-500 mb-2"></i>
              <span className="text-xl font-black text-gray-800 dark:text-white uppercase tracking-tighter">Concluído!</span>
            </div>
          ) : (
            <>
              <span className="text-6xl font-black text-gray-800 dark:text-white tabular-nums tracking-tighter">
                {formatTime(secondsLeft)}
              </span>
              <span className="text-xs font-bold text-gray-400 dark:text-gray-600 uppercase tracking-widest mt-2">restantes</span>
            </>
          )}
        </div>
      </div>

      {/* Controls */}
      <div className="w-full max-w-xs space-y-4 pb-12">
        {!isFinished && (
          <>
            <button 
              onClick={() => setIsActive(!isActive)}
              className="w-full py-5 rounded-3xl font-black text-xs uppercase tracking-[0.2em] shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3"
              style={{ backgroundColor: objective.color, color: '#fff' }}
            >
              <i className={`fas ${isActive ? 'fa-pause' : 'fa-play'}`}></i>
              {isActive ? 'Pausar Sprint' : 'Retomar Sprint'}
            </button>
            <button 
              onClick={handleManualExitAttempt}
              className="w-full py-4 text-gray-400 dark:text-gray-600 font-bold text-xs uppercase tracking-widest hover:text-red-500 transition-colors"
            >
              Finalizar Agora
            </button>
          </>
        )}
      </div>

      {/* Confirmation Modal */}
      {showExitConfirm && (
        <div className="fixed inset-0 z-[70] bg-white/80 dark:bg-gray-950/80 backdrop-blur-md flex items-center justify-center p-6 animate-in fade-in duration-200">
          <div className="bg-white dark:bg-gray-900 w-full max-w-sm rounded-3xl p-8 shadow-2xl border border-gray-100 dark:border-gray-800 text-center space-y-6">
            <div className="w-16 h-16 bg-red-50 dark:bg-red-900/20 rounded-full flex items-center justify-center mx-auto text-red-500">
              <i className="fas fa-exclamation-triangle text-2xl"></i>
            </div>
            <div className="space-y-2">
              <h3 className="text-lg font-black text-gray-800 dark:text-white uppercase tracking-tight">Interromper Sprint?</h3>
              <p className="text-sm text-gray-500 dark:text-gray-400 leading-relaxed">
                Se você finalizar agora, este sprint será <span className="font-bold text-red-500">zerado</span> e não será contabilizado como concluído.
              </p>
            </div>
            <div className="space-y-3 pt-2">
              <button 
                onClick={confirmExit}
                className="w-full py-4 bg-red-500 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-red-600 transition-colors"
              >
                Sim, finalizar sem salvar
              </button>
              <button 
                onClick={() => setShowExitConfirm(false)}
                className="w-full py-4 bg-gray-100 dark:bg-gray-800 text-gray-800 dark:text-gray-200 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
              >
                Não, continuar focado
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Background Decorative Element */}
      <div 
        className="absolute -bottom-24 -left-24 w-64 h-64 rounded-full opacity-5 blur-3xl pointer-events-none"
        style={{ backgroundColor: objective.color }}
      ></div>
    </div>
  );
};

export default TimerView;

import React, { useMemo, useState, useEffect } from 'react';
import { Objective } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer } from 'recharts';

interface Props {
  objectives: Objective[];
}

const StatsOverview: React.FC<Props> = ({ objectives }) => {
  const isDarkMode = document.documentElement.classList.contains('dark');

  const [isObjectivesExpanded, setIsObjectivesExpanded] = useState<boolean>(() => {
    const saved = localStorage.getItem('sprint_stats_expanded');
    return saved === null ? true : saved === 'true';
  });

  useEffect(() => {
    localStorage.setItem('sprint_stats_expanded', String(isObjectivesExpanded));
  }, [isObjectivesExpanded]);

  const stats = useMemo(() => {
    const totalSprints = objectives.reduce((acc, obj) => acc + obj.completions.length, 0);
    const totalMinutes = objectives.reduce((acc, obj) => acc + (obj.completions.length * (obj.duration || 0)), 0);

    const objectivesProgress = objectives.map(obj => {
      const startOfPeriod = new Date();
      if (obj.frequency === 'daily') startOfPeriod.setHours(0, 0, 0, 0);
      else if (obj.frequency === 'weekly') {
        const day = startOfPeriod.getDay();
        const diff = startOfPeriod.getDate() - day + (day === 0 ? -6 : 1);
        startOfPeriod.setDate(diff);
        startOfPeriod.setHours(0, 0, 0, 0);
      } else if (obj.frequency === 'monthly') {
        startOfPeriod.setDate(1);
        startOfPeriod.setHours(0, 0, 0, 0);
      } else {
        startOfPeriod.setMonth(0, 1);
        startOfPeriod.setHours(0, 0, 0, 0);
      }

      const count = obj.completions.filter(c => c.timestamp >= startOfPeriod.getTime()).length;
      // Proteção contra divisão por zero
      const target = obj.targetCount > 0 ? obj.targetCount : 1;
      const percent = Math.min((count / target) * 100, 100);

      return { ...obj, currentCount: count, percent };
    });

    const avgSuccessRate = objectivesProgress.length > 0 
      ? Math.round(objectivesProgress.reduce((a, b) => a + b.percent, 0) / objectivesProgress.length) 
      : 0;

    const hours = Math.floor(totalMinutes / 60);
    const mins = totalMinutes % 60;

    return { totalSprints, hours, mins, avgSuccessRate, objectivesProgress };
  }, [objectives]);

  // Garante que o gráfico sempre tenha dados válidos
  const safeRate = isNaN(stats.avgSuccessRate) ? 0 : stats.avgSuccessRate;
  const pieData = [
    { value: safeRate },
    { value: 100 - safeRate }
  ];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-2 duration-700 pb-12">

      {/* Visão Geral - Anel de Conclusão */}
      <div className="flex flex-col items-center justify-center pt-4">
        <div className="relative w-48 h-48">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={pieData}
                innerRadius={70}
                outerRadius={85}
                startAngle={90}
                endAngle={450}
                paddingAngle={0}
                dataKey="value"
                stroke="none"
                animationDuration={1000}
              >
                <Cell fill={isDarkMode ? '#6366f1' : '#4f46e5'} />
                <Cell fill={isDarkMode ? '#1e293b' : '#f1f5f9'} />
              </Pie>
            </PieChart>
          </ResponsiveContainer>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className="text-4xl font-black text-gray-800 dark:text-white leading-none">{safeRate}%</span>
            <span className="text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mt-1">Concluído</span>
          </div>
        </div>
        <div className="mt-6 text-center">
          <h2 className="text-lg font-bold text-gray-800 dark:text-gray-100">Foco Geral</h2>
          <p className="text-sm text-gray-400 dark:text-gray-500">Média de progresso do período atual</p>
        </div>
      </div>

      {/* Métricas Rápidas */}
      <div className="grid grid-cols-2 gap-4 px-2">
        <div className="bg-white dark:bg-gray-900 rounded-2xl p-4 border border-gray-100 dark:border-gray-800/50 flex flex-col items-center justify-center text-center">
          <div className="w-8 h-8 rounded-full bg-indigo-50 dark:bg-indigo-900/20 flex items-center justify-center text-indigo-500 text-xs mb-2">
            <i className="fas fa-bolt"></i>
          </div>
          <span className="text-[9px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-1">Sprints</span>
          <p className="text-xl font-black text-gray-800 dark:text-white leading-none">{stats.totalSprints}</p>
        </div>

        <div className="bg-white dark:bg-gray-900 rounded-2xl p-4 border border-gray-100 dark:border-gray-800/50 flex flex-col items-center justify-center text-center">
          <div className="w-8 h-8 rounded-full bg-indigo-50 dark:bg-indigo-900/20 flex items-center justify-center text-indigo-500 text-xs mb-2">
            <i className="fas fa-hourglass-half"></i>
          </div>
          <span className="text-[9px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-1">Tempo</span>
          <p className="text-xl font-black text-gray-800 dark:text-white leading-none">{stats.hours}h {stats.mins}m</p>
        </div>
      </div>

      {/* Lista de Objetivos Individuais */}
      <div className="space-y-4 px-2 transition-all duration-300">
        <button 
          onClick={() => setIsObjectivesExpanded(!isObjectivesExpanded)}
          className="w-full flex items-center justify-between mb-2 group focus:outline-none"
        >
          <div className="flex items-center gap-2">
            <h3 className="text-sm font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest group-hover:text-indigo-500 transition-colors">Objetivos Individuais</h3>
            <span className="text-[10px] font-medium text-gray-300 dark:text-gray-700">({objectives.length})</span>
          </div>
          <i className={`fas fa-chevron-down text-gray-300 dark:text-gray-700 transition-transform duration-300 ${isObjectivesExpanded ? 'rotate-180' : ''}`}></i>
        </button>

        {isObjectivesExpanded && (
          <div className="space-y-5 animate-in slide-in-from-top-2 duration-300">
            {stats.objectivesProgress.length === 0 ? (
              <div className="py-12 text-center text-gray-400 dark:text-gray-600 text-sm border border-gray-100 dark:border-gray-800 rounded-2xl shadow-sm">
                Nenhum objetivo para analisar
              </div>
            ) : (
              stats.objectivesProgress.map((obj) => (
                <div key={obj.id} className="group">
                  <div className="flex justify-between items-end mb-2">
                    <div className="flex items-center gap-2">
                      <div className="w-2 h-2 rounded-full" style={{ backgroundColor: obj.color }}></div>
                      <span className="text-sm font-bold text-gray-700 dark:text-gray-200">{obj.title}</span>
                    </div>
                    <span className="text-xs font-black text-gray-400 dark:text-gray-600">
                      {obj.currentCount} / {obj.targetCount}
                    </span>
                  </div>
                  <div className="h-1.5 w-full bg-gray-100 dark:bg-gray-800 rounded-full overflow-hidden">
                    <div 
                      className="h-full rounded-full transition-all duration-1000 ease-out"
                      style={{ 
                        width: `${obj.percent}%`,
                        backgroundColor: obj.color
                      }}
                    ></div>
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="pt-4 text-center">
        <div className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-50 dark:bg-indigo-900/10 rounded-full">
          <span className="relative flex h-2 w-2">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-indigo-400 opacity-75"></span>
            <span className="relative inline-flex rounded-full h-2 w-2 bg-indigo-500"></span>
          </span>
          <span className="text-[10px] font-bold text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">
            Sincronizado e Ativo
          </span>
        </div>
      </div>

    </div>
  );
};

