          {/* Círculos de Pulsação */}
          <div className="absolute inset-0 bg-indigo-500/20 rounded-full animate-ping"></div>
          <div className="w-24 h-24 bg-gradient-to-tr from-indigo-600 to-purple-600 rounded-3xl flex items-center justify-center shadow-2xl shadow-indigo-500/40 relative">
            <i className="fas fa-bolt text-4xl text-white"></i>
          </div>
