        <div className="text-center space-y-2 animate-in fade-in slide-in-from-bottom-4 duration-700">
          <h1 className="text-4xl font-black text-gray-900 dark:text-white tracking-[0.2em] mb-1">
            SPRINT
          </h1>
          <p className="text-gray-400 dark:text-gray-500 font-medium text-sm uppercase tracking-widest">
            Transforme intenção em ação
          </p>
        </div>
      </div>

      {/* Botão de Entrada (Apenas na primeira vez) */}
      {isFirstTime && (
        <div className="absolute bottom-16 w-full px-8 max-w-xs animate-in fade-in slide-in-from-bottom-8 duration-700 delay-300">
          <button 
            onClick={handleDismiss}
