      )}

      {/* Indicador de carregamento (Apenas se for retorno automático) */}
      {!isFirstTime && (
        <div className="absolute bottom-20 flex gap-1.5 animate-in fade-in duration-700 delay-300">
          <div className="w-1.5 h-1.5 rounded-full bg-indigo-500/40 animate-bounce [animation-delay:-0.3s]"></div>
