import React, { useState, useEffect } from 'react';

interface Props {
  onComplete: () => void;
}

const SplashScreen: React.FC<Props> = ({ onComplete }) => {
  const [isVisible, setIsVisible] = useState(true);
  const [isExiting, setIsExiting] = useState(false);
  const [isFirstTime] = useState(() => {
    return !localStorage.getItem('sprint_onboarded');
  });

  const handleDismiss = () => {
    setIsExiting(true);
    if (isFirstTime) {
      localStorage.setItem('sprint_onboarded', 'true');
    }
    setTimeout(() => {
      setIsVisible(false);
      onComplete();
    }, 600);
  };

  useEffect(() => {
    if (!isFirstTime) {
      const timer = setTimeout(() => {
        handleDismiss();
      }, 1400);
      return () => clearTimeout(timer);
    }
  }, [isFirstTime]);

  if (!isVisible) return null;

  return (
    <div 
      className={`fixed inset-0 z-[100] flex flex-col items-center justify-center transition-all duration-700 ease-in-out ${
        isExiting ? 'opacity-0 scale-110 pointer-events-none' : 'opacity-100'
      } bg-white dark:bg-gray-950`}
    >
      {/* Background Decorativo */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-500/10 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-purple-500/10 blur-[120px] rounded-full"></div>
      </div>

      {/* Conteúdo Central */}
      <div className="relative z-10 flex flex-col items-center">
        <div className="mb-8 relative">
          {/* Círculos de Pulsação */}
          <div className="absolute inset-0 bg-indigo-500/20 rounded-[30%] animate-ping"></div>

          {/* Ícone customizado baseado na imagem do usuário */}
          <div className="w-24 h-24 bg-gradient-to-br from-[#5D5FEF] to-[#A559FF] rounded-[30%] flex items-center justify-center shadow-2xl shadow-indigo-500/40 relative transform-none">
            <i className="fas fa-bolt text-4xl text-white drop-shadow-md"></i>
          </div>
        </div>

        <div className="text-center space-y-2 animate-in fade-in slide-in-from-bottom-4 duration-700">
          <h1 className="text-4xl font-black text-gray-900 dark:text-white tracking-[0.2em] mb-1">
            SPRINT
          </h1>
          <p className="text-gray-400 dark:text-gray-500 font-medium text-xs uppercase tracking-[0.3em]">
            Transforme intenção em ação
          </p>
        </div>
      </div>

      {/* Botão de Entrada (Apenas na primeira vez) */}
      {isFirstTime && (
        <div className="absolute bottom-16 w-full px-8 max-w-xs animate-in fade-in slide-in-from-bottom-8 duration-700 delay-300">
          <button 
            onClick={handleDismiss}
            className="w-full py-5 bg-gray-900 dark:bg-white text-white dark:text-gray-950 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl hover:scale-105 active:scale-95 transition-all group overflow-hidden relative"
          >
            <span className="relative z-10">Começar Jornada</span>
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000"></div>
          </button>
        </div>
      )}

      {/* Indicador de carregamento (Apenas se for retorno automático) */}
      {!isFirstTime && (
        <div className="absolute bottom-20 flex gap-1.5 animate-in fade-in duration-700 delay-300">
          <div className="w-1.5 h-1.5 rounded-full bg-indigo-500/40 animate-bounce [animation-delay:-0.3s]"></div>
          <div className="w-1.5 h-1.5 rounded-full bg-indigo-500/40 animate-bounce [animation-delay:-0.15s]"></div>
          <div className="w-1.5 h-1.5 rounded-full bg-indigo-500/40 animate-bounce"></div>
