import React, { useState, useEffect } from 'react';
import { Objective } from './types';
import ObjectiveCard from './components/ObjectiveCard';
import AddObjectiveModal from './components/AddObjectiveModal';
import Header from './components/Header';
import StatsOverview from './components/StatsOverview';
import TimerView from './components/TimerView';
import SplashScreen from './components/SplashScreen';
import ProfileView from './components/ProfileView';

const App: React.FC = () => {
  const [objectives, setObjectives] = useState<Objective[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingObjective, setEditingObjective] = useState<Objective | null>(null);
  const [activeSprint, setActiveSprint] = useState<Objective | null>(null);
  const [activeTab, setActiveTab] = useState<'objectives' | 'stats' | 'profile'>('objectives');

  const [showSplash, setShowSplash] = useState(true);

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('sprint_theme');
    if (saved === 'light' || saved === 'dark') return saved;
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  useEffect(() => {
    const setHeight = () => {
      document.documentElement.style.setProperty('--app-height', `${window.innerHeight}px`);
    };
    window.addEventListener('resize', setHeight);
    setHeight();
    return () => window.removeEventListener('resize', setHeight);
  }, []);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('sprint_theme', theme);
  }, [theme]);

  useEffect(() => {
    const saved = localStorage.getItem('sprint_objectives');
    if (saved) {
      try {
        setObjectives(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse objectives", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('sprint_objectives', JSON.stringify(objectives));
  }, [objectives]);

  const toggleTheme = () => setTheme(prev => prev === 'light' ? 'dark' : 'light');

  const handleSplashComplete = () => {
    setShowSplash(false);
  };

  const handleModalSubmit = (data: Omit<Objective, 'id' | 'createdAt' | 'completions'>) => {
    if (editingObjective) {
      setObjectives(prev => prev.map(obj => 
        obj.id === editingObjective.id ? { ...obj, ...data } : obj
      ));
    } else {
      const obj: Objective = {
        ...data,
        id: crypto.randomUUID(),
        createdAt: Date.now(),
        completions: []
      };
      setObjectives(prev => [...prev, obj]);
    }
    closeModal();
  };

  const openAddModal = () => {
    setEditingObjective(null);
    setIsModalOpen(true);
  };

  const openEditModal = (obj: Objective) => {
    setEditingObjective(obj);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingObjective(null);
  };

  const deleteObjective = (id: string) => {
    if (confirm('Deseja realmente excluir este objetivo?')) {
      setObjectives(prev => prev.filter(o => o.id !== id));
    }
  };

  const completeSprint = (id: string) => {
    setObjectives(prev => prev.map(obj => {
      if (obj.id === id) {
        return {
          ...obj,
          completions: [...obj.completions, { timestamp: Date.now() }]
        };
      }
      return obj;
    }));
  };

  const startSprintTimer = (obj: Objective) => {
    setActiveSprint(obj);
  };

  return (
    <>
      {showSplash && <SplashScreen onComplete={handleSplashComplete} />}

      <div 
        className={`flex flex-col bg-gray-50 dark:bg-gray-950 max-w-2xl mx-auto shadow-xl dark:shadow-none w-full relative transition-opacity duration-1000 ${showSplash ? 'opacity-0' : 'opacity-100'}`}
        style={{ height: 'var(--app-height)' }}
      >
        <Header theme={theme} onToggleTheme={toggleTheme} />

        <main className="main-content p-4 space-y-6 pb-20">
          {activeTab === 'objectives' && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h2 className="text-xl font-bold text-gray-800 dark:text-gray-100">Seus Objetivos</h2>
                <button 
                  onClick={openAddModal}
                  className="bg-indigo-600 text-white w-10 h-10 rounded-full flex items-center justify-center shadow-lg hover:bg-indigo-700 transition-colors active:scale-90"
                >
                  <i className="fas fa-plus"></i>
                </button>
              </div>

              {objectives.length === 0 ? (
                <div className="text-center py-12 px-6 bg-white dark:bg-gray-900 rounded-2xl border border-gray-100 dark:border-gray-800 shadow-sm">
                  <div className="bg-indigo-50 dark:bg-indigo-900/30 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                    <i className="fas fa-bullseye text-indigo-400 text-2xl"></i>
                  </div>
                  <h3 className="text-gray-700 dark:text-gray-200 font-medium text-lg">Nenhum objetivo ainda</h3>
                  <p className="text-gray-500 dark:text-gray-400 mt-2">Adicione seu primeiro objetivo para começar sua jornada de desenvolvimento.</p>
                  <button 
                    onClick={openAddModal}
                    className="mt-6 px-6 py-2 bg-indigo-600 text-white rounded-lg font-semibold active:scale-95 transition-transform"
                  >
                    Adicionar Objetivo
                  </button>
                </div>
              ) : (
                <div className="grid gap-4">
                  {objectives.map(obj => (
                    <ObjectiveCard 
                      key={obj.id} 
                      objective={obj} 
                      onComplete={() => startSprintTimer(obj)}
                      onDelete={() => deleteObjective(obj.id)}
                      onEdit={() => openEditModal(obj)}
                    />
                  ))}
                </div>
              )}
            </div>
          )}

          {activeTab === 'stats' && <StatsOverview objectives={objectives} />}
          {activeTab === 'profile' && <ProfileView />}
        </main>

        <nav className="shrink-0 bg-white/80 dark:bg-gray-900/80 backdrop-blur-md border-t border-gray-100 dark:border-gray-800 px-6 py-3 flex justify-around items-center max-w-2xl mx-auto w-full z-40">
          <button 
            onClick={() => setActiveTab('objectives')}
            className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'objectives' ? 'text-indigo-600 dark:text-indigo-400' : 'text-gray-400 dark:text-gray-600'}`}
          >
            <i className="fas fa-list-check text-xl"></i>
            <span className="text-[10px] font-semibold">Sprint</span>
          </button>
          <button 
            onClick={() => setActiveTab('stats')}
            className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'stats' ? 'text-indigo-600 dark:text-indigo-400' : 'text-gray-400 dark:text-gray-600'}`}
          >
            <i className="fas fa-chart-line text-xl"></i>
            <span className="text-[10px] font-semibold">Progresso</span>
          </button>
          <button 
            onClick={() => setActiveTab('profile')}
            className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'profile' ? 'text-indigo-600 dark:text-indigo-400' : 'text-gray-400 dark:text-gray-600'}`}
          >
            <i className="fas fa-user text-xl"></i>
            <span className="text-[10px] font-semibold">Perfil</span>
          </button>
        </nav>

        <AddObjectiveModal 
          isOpen={isModalOpen} 
          onClose={closeModal} 
          onSubmit={handleModalSubmit} 
          initialData={editingObjective}
        />

        {activeSprint && (
          <TimerView 
            objective={activeSprint}
            onClose={() => setActiveSprint(null)}
            onComplete={() => completeSprint(activeSprint.id)}
          />
        )}
      </div>
    </>
  );
};

export default App;

import React, { useState, useEffect } from 'react';

const ProfileView: React.FC = () => {
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isInstalled, setIsInstalled] = useState(false);

  useEffect(() => {
    // Detecta se já está instalado (modo standalone)
    if (window.matchMedia('(display-mode: standalone)').matches) {
      setIsInstalled(true);
    }

    const handleBeforeInstallPrompt = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    };
  }, []);

  const handleInstallClick = async () => {
    if (!deferredPrompt) return;

    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;

    if (outcome === 'accepted') {
      setDeferredPrompt(null);
      setIsInstalled(true);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center pt-10 space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Área do Ícone de Perfil */}
      <div className="flex flex-col items-center space-y-4">
        <div className="relative group">
          <div className="absolute inset-0 bg-gradient-to-br from-[#5D5FEF] to-[#A559FF] rounded-full blur-2xl opacity-20 group-hover:opacity-40 transition-opacity"></div>
          <div className="w-32 h-32 bg-gray-100 dark:bg-gray-900 rounded-full flex items-center justify-center border-4 border-white dark:border-gray-800 shadow-xl relative z-10">
            <i className="fas fa-user text-5xl text-gray-300 dark:text-gray-700"></i>
          </div>
          <button className="absolute bottom-1 right-1 w-9 h-9 bg-indigo-600 text-white rounded-full flex items-center justify-center shadow-lg border-2 border-white dark:border-gray-900 active:scale-90 transition-transform z-20">
            <i className="fas fa-camera text-xs"></i>
          </button>
        </div>
        <div className="text-center">
          <h2 className="text-xl font-black text-gray-800 dark:text-white uppercase tracking-tight">Atleta Sprint</h2>
          <p className="text-xs font-bold text-gray-400 dark:text-gray-600 uppercase tracking-[0.2em] mt-1">Nível 1 • Iniciante</p>
        </div>
      </div>

      {/* Botão de Instalação */}
      <div className="w-full max-w-xs space-y-4">
        {!isInstalled && deferredPrompt && (
          <div className="bg-white dark:bg-gray-900 p-6 rounded-3xl border border-gray-100 dark:border-gray-800 shadow-sm space-y-4">
            <div className="flex items-center gap-3 mb-2 text-indigo-500">
              <i className="fas fa-mobile-screen-button text-xl"></i>
              <span className="font-black text-[10px] uppercase tracking-widest">Experiência Completa</span>
            </div>
            <p className="text-sm text-gray-500 dark:text-gray-400 leading-relaxed">
              Instale o Sprint na sua tela de início para acesso rápido e notificações de foco.
            </p>
            <button 
              onClick={handleInstallClick}
              className="w-full py-4 bg-gray-950 dark:bg-white text-white dark:text-gray-950 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl hover:scale-105 active:scale-95 transition-all"
            >
              Instalar Aplicativo
            </button>
          </div>
        )}

        {isInstalled && (
          <div className="text-center p-6 bg-green-50 dark:bg-green-900/10 rounded-3xl border border-green-100 dark:border-green-800/20">
            <i className="fas fa-check-circle text-green-500 mb-2 text-xl"></i>
            <p className="text-xs font-bold text-green-600 dark:text-green-400 uppercase tracking-widest">App Instalado com Sucesso</p>
          </div>
        )}

        {!isInstalled && !deferredPrompt && (
          <div className="bg-white dark:bg-gray-900 p-6 rounded-3xl border border-gray-100 dark:border-gray-800 shadow-sm text-center">
            <p className="text-xs text-gray-400 dark:text-gray-600 font-medium leading-relaxed">
              Para instalar, use a opção "Adicionar à tela de início" do seu navegador.
            </p>
          </div>
        )}
      </div>

      {/* Link de Ajuda / Configurações Simples */}
      <div className="pt-4">
        <button className="text-[10px] font-black text-gray-300 dark:text-gray-700 uppercase tracking-[0.3em] hover:text-indigo-500 transition-colors">
          Configurações da Conta
        </button>
      </div>
    </div>
  );
};

export default ProfileView;
